  const fields = el('div', { class: 'composer-fields' }); const preview = el('aside', { class: 'composer-preview', 'aria-label': 'Post preview' }); const grid = el('div', { class: 'composer-grid' }, fields, preview);
  const name = el('input', { class: 'field-control title-control', id: 'post-title', name: 'title', placeholder: 'Give this plan a working title…', maxlength: 200, required: '', autocomplete: 'off' }); name.value = draft.name;
  const choices = el('div', { class: 'platform-choices' }); const tabs = el('div', { class: 'caption-tabs', role: 'tablist', 'aria-label': 'Account captions' }); const postFields = el('div', { class: 'post-editor' });
  const date = el('input', { class: 'field-control', type: 'datetime-local', id: 'post-date', name: 'scheduledFor', required: '' }); date.value = scheduleInZone(draft.scheduledFor, zone);
  const timeZone = el('input', { class: 'field-control', id: 'post-timezone', name: 'timezone', required: '', list: 'timezones', autocomplete: 'off' }); timeZone.value = zone;
  const zones = el('datalist', { id: 'timezones' }, ...[zone, 'UTC', 'America/New_York', 'America/Los_Angeles', 'Europe/London', 'Asia/Kolkata', 'Asia/Singapore', 'Australia/Sydney'].filter((v, i, all) => all.indexOf(v) === i).map((v) => el('option', { value: v })));
  const errors = el('div', { class: 'validation-errors', role: 'alert', tabindex: '-1', hidden: '' });
