  fields.append(field('Working title', name), el('div', { class: 'field-group' }, el('span', { class: 'field-label', text: 'Channels' }), choices), el('div', { class: 'account-tab-bar' }, tabs, button('＋ Accounts', selectAccounts, 'small')), postFields, el('div', { class: 'schedule-editor' }, field('Date & time', date), field('Time zone', timeZone), zones), errors, previewToggle);
