    for (const p of PLATFORMS) for (const account of accountsFor(data, p.id)) { const check = el('input', { type: 'checkbox', checked: selected.has(account.id), 'aria-label': `Use ${p.name} account ${accountName(account)}` }); check.addEventListener('change', () => { if (check.checked) selected.set(account.id, { targetId: targetId(), channel: p.id, accountId: account.id, text: current()?.text || '', mediaIds: [...(current()?.mediaIds || [])], format: 'feed' }); else selected.delete(account.id); }); choose.content.append(el('label', { class: 'account-choice' }, check, el('span', { class: `platform-icon ${p.id}`, text: p.icon }), el('span', {}, el('strong', { text: accountName(account) }), el('small', { text: account.externalAccountId })))); }
